": true}, {"id": "tool.chart.render", "label": "图表渲染", "enabled": true}], "answer": [{"id": "answer.qa.structured", "label": "结构化问答", "enabled": true}, {"id": "answer.market.deep", "label": "研究型回答", "enabled": true}, {"id": "answer.report.evidence", "label": "报告 / 证据链回答", "enabled": true}, {"id": "answer.redirect.soft", "label": "温和收口", "enabled": true}], "render": [{"id": "render.text", "label": "文本结果", "enabled": true}, {"id": "render.metric_cards", "label": "指标卡片", "enabled": true}, {"id": "render.chart_kline", "label": "K 线图", "enabled": true}, {"id": "render.chart_line", "label": "线性图", "enabled": true}, {"id": "render.chart_distribution", "label": "分布图", "enabled": true}, {"id": "render.followup_tags", "label": "追问标签", "enabled": true}, {"id": "render.thinking_stream", "label": "思考过程", "enabled": true}]}}, "evidence_chain": {"filter_prompt_system": "你是知识检索相关性过滤助手。你的任务是根据用户问题，从召回候选里剔除明显无关、仅语义相近但业务主题不一致的内容。判断标准必须严格，只有真正能回答问题、或能提供直接支撑信息的知识才能保留。如果问题是具体领域问题，例如 MES、制造、设备、工艺，就不要保留股票、行情、复盘、泛化观点等无关内容。输出必须是 JSON，不要输出任何额外解释。", "filter_prompt_user_template": "用户问题：{query}\n\n候选知识：\n{candidate_blocks}\n\n请返回 JSON，格式如下：\n{\n  \"relevant_ids\": [\"保留的候选ID\"],\n  \"reason\": \"一句话说明筛选结论\"\n}\n如果没有任何相关知识，relevant_ids 返回空数组。", "filter_timeout_seconds": 25, "answer_timeout_seconds": 45}, "review_generation": {"polish_system_prompt": "你是中文投研复盘助手。你的任务是先对大V输入的原始材料做轻量整理和润色，删除明显重复、口语噪音和无效赘述，但必须保留原有事实、判断、风险提示和不确定性。不要新增原文没有出现的观点、数据和投资建议。输出纯文本，按自然段组织，保持便于后续继续组合成完整复盘。", "polish_user_template": "复盘周期：{period_label}\n输入来源：{source_mode}\n作者：{speaker_label}\n触发入口：{entry_point}\n\n请先把下面的原始输入整理成更干净、更适合后续继续生成复盘正文的中间稿。重点保留：市场主线、行业判断、重点个股、验证节点、风险边界。\n\n原始输入：\n{source_text}", "compose_system_prompt": "你是中文投研复盘编辑助手。你要基于大V自己的输入，以及已选中的智能仪表盘卡片，生成一版完整复盘草稿。必须优先保留大V自己的核心判断和风险表达，智能仪表盘只用于补充证据、结构和验证节点。不要编造事实、数字、新闻或结论。输出纯文本，语言专业、克制、可直接给大V继续人工修改。尽量压缩表达，草稿长度默认应少于原始输入长度。", "compose_user_template": "复盘周期：{period_label}\n作者：{speaker_label}\n触发入口：{entry_point}\n纳入样本：{watchlist_text}\n附加标签：{tag_text}\n额外要求：{prompt_text}\n\n这是大V最终确认前的复盘草稿，请基于以下两部分内容生成：\n1. 大V输入/润色稿\n2. 智能仪表盘卡片摘要（每张卡片都附有数据来源和新闻来源）\n3. 大V已选择的知识材料\n\n大V输入：\n{source_text}\n\n智能仪表盘卡片：\n{dashboard_blocks}\n\n知识材料：\n{knowledge_blocks}\n\n请直接输出最终复盘草稿，不要解释处理过程，不要输出“以下是结果”等前缀。", "polish_timeout_seconds": 45, "compose_timeout_seconds": 60}, "llm_registry": {"default_model_key": "volcengine-deepseek-v4-flash", "models": [{"key": "open_webui_qwen35_27b", "label": "Open WebUI Qwen 3.5 27B", "provider": "openai", "model_name": "qwen3.5:27b-q4_K_M", "base_url": "http://8.155.160.194:6031/api", "api_key": "", "purpose": "general", "enabled": true}, {"key": "open_webui_gemma4_31b", "label": "Open WebUI Gemma 4 31B", "provider": "openai", "model_name": "gemma4:31b-it-q8_0", "base_url": "http://8.155.160.194:6031/api", "api_key": "", "purpose": "general", "enabled": true}, {"key": "gangtise-gemma4-31b-q4km", "label": "Gangtise Gemma4 31B Q4_K_M", "provider": "openai", "model_name": "gemma4:31b-it-q4_K_M", "base_url": "http://8.155.160.194:6031/api", "api_key": "", "purpose": "general", "enabled": true}, {"key": "gangtise-gemma4-12b-bf16", "label": "Gangtise Gemma4 12B BF16", "provider": "openai", "model_name": "gemma4:12b-it-bf16", "base_url": "http://8.155.160.194:6031/api", "api_key": "", "purpose": "general", "enabled": true}, {"key": "volcengine-deepseek-v4-flash", "label": "DeepSeek-V4-Flash正式版", "provider": "volcengine", "model_name": "deepseek-v4-flash-ga-260731", "base_url": "https://ark.cn-beijing.volces.com/api/v3", "api_key": "", "purpose": "general", "enabled": true}], "feature_model_keys": {"review_voice_enhancement": "gangtise-gemma4-12b-bf16"}}, "brand": {"name": "洞见智研", "short_name": "洞见智研", "logo_mark": "洞", "logo_url": "", "tagline": "智能投研平台", "hero_tagline": "聚焦复盘、基本面分析、自选股诊断与证据链输出的智能投研能力", "hero_description": "当前定位不是泛金融 SaaS，而是面向研究场景的第三方智能投研工具与服务层。面向普通投资者、大V投顾租户和平台 Admin 提供多角色隔离、按需基本面、工作台协同与合规表达能力。", "footer_description": "整合券商研报、专家纪要与市场数据，以 AI 驱动的证据链和工作流工具服务研究型大V投顾、机构与普通投资者，持续沉淀可复用的方法论资产。"}, "default_tenant_s